<?php $reference = $_SESSION['submitted_reference'] ?? null; unset($_SESSION['submitted_reference']); $settings = site_settings(); $phone = preg_replace('/\D+/', '', $settings['whatsapp'] ?? ''); $waUrl = $phone ? 'https://wa.me/' . $phone . '?text=' . rawurlencode('Bonjour, je viens de soumettre une candidature au programme. Mon numéro de dossier est ' . ($reference ?? '') . '. Je souhaite obtenir des informations concernant la suite de ma candidature.') : ''; ?>
<section class="section section-paper confirmation-section"><div class="container confirmation-card"><div class="confirmation-icon"><i class="bi bi-check2"></i></div><p class="eyebrow eyebrow-dark"><span></span><?= e(tr('CANDIDATURE ENREGISTRÉE', 'APPLICATION RECEIVED')) ?></p><h1><?= e(tr('Votre candidature a bien été enregistrée.', 'Your application has been received.')) ?></h1><?php if ($reference): ?><p><?= e(tr('Votre numéro de dossier :','Your application reference:')) ?></p><div class="reference-number"><?= e($reference) ?></div><p><?= e(tr('Conservez précieusement ce numéro. Il pourra être utilisé pour suivre votre candidature.', 'Keep this reference safe. You will need it to track your application.')) ?></p><?php else: ?><p><?= e(tr('Aucun nouveau numéro de dossier n’est disponible dans cette session.', 'No new application reference is available in this session.')) ?></p><?php endif; ?><div class="confirmation-actions"><a class="button button-green" href="<?= e(url('track')) ?>"><?= e(tr('Suivre ma candidature','Track my application')) ?> <i class="bi bi-arrow-right"></i></a><?php if($waUrl): ?><a class="button button-outline-dark" href="<?= e($waUrl) ?>" target="_blank" rel="noopener noreferrer"><i class="bi bi-whatsapp"></i> <?= e(tr('Contacter l’équipe sur WhatsApp','Contact the team on WhatsApp')) ?></a><?php endif; ?><a class="text-link" href="index.php"><?= e(tr('Retour à l’accueil','Back to home')) ?></a></div><p class="form-disclaimer"><?= e(tr('Le dépôt d’une candidature ne garantit pas un financement.','Submitting an application does not guarantee funding.')) ?></p></div></section>
